#include <iostream>
using namespace std;

int cube(int x) {
    int result = x * x * x;
    return result;
}

int main() {
    int n;
    cout << "Enter a number: ";
    cin >> n;

    int answer = 0;
    cube(n);

    cout << "Cube: " << answer << endl;
    return 0;
}

